import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(t):
        try:
            n = int(next(iterator))
            k = int(next(iterator))

            friends = set()
            for _ in range(k):
                friends.add(int(next(iterator)))

            adj = [[] for _ in range(n + 1)]
            for _ in range(n - 1):
                u = int(next(iterator))
                v = int(next(iterator))
                adj[u].append(v)
                adj[v].append(u)

            dist_friend = [-1] * (n + 1)
            queue = deque()

            for f in friends:
                dist_friend[f] = 0
                queue.append(f)

            while queue:
                u = queue.popleft()
                d = dist_friend[u]
                for v in adj[u]:
                    if dist_friend[v] == -1:
                        dist_friend[v] = d + 1
                        queue.append(v)

            can_win = False
            q_vlad = deque()
            visited = [False] * (n + 1)

            if dist_friend[1] > 0:
                q_vlad.append(1)
                visited[1] = True

            while q_vlad:
                u = q_vlad.popleft()

                if len(adj[u]) == 1 and u != 1:
                    if dist_friend[u] > dist_friend[1] + (dist_friend[u] - dist_friend[1]):
                        pass
                    if dist_friend[u] > dist_friend[1] + 0:
                        can_win = True
                        break
                    else:
                        pass

                for v in adj[u]:
                    if not visited[v]:
                        if dist_friend[v] > dist_friend[u] + 1:
                            visited[v] = True
                            q_vlad.append(v)
                        else:
                            pass

            if can_win:
                results.append("YES")
            else:
                results.append("NO")

        except StopIteration:
            break

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
